def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [[0] * w for _ in range(h)]
    cells_by_color = {}
    for r in range(h):
        for c in range(w):
            if grid[r][c]:
                cells_by_color.setdefault(grid[r][c], set()).add((r, c))

    frames = []
    frame_cells = set()
    for color, cells in cells_by_color.items():
        r0 = min(r for r, c in cells)
        r1 = max(r for r, c in cells)
        c0 = min(c for r, c in cells)
        c1 = max(c for r, c in cells)
        if r1 - r0 < 2 or c1 - c0 < 2:
            continue
        border = {
            (r, c)
            for r in range(r0, r1 + 1)
            for c in range(c0, c1 + 1)
            if r in (r0, r1) or c in (c0, c1)
        }
        if cells == border:
            frames.append((color, r0, r1, c0, c1))
            frame_cells |= border

    marker_counts = {}
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color and (r, c) not in frame_cells:
                marker_counts[color] = marker_counts.get(color, 0) + 1

    for color, r0, r1, c0, c1 in frames:
        for r in range(r0, r1 + 1):
            for c in range(c0, c1 + 1):
                if r in (r0, r1) or c in (c0, c1):
                    out[r][c] = color

        interior = [
            (r, c)
            for r in range(r0 + 1, r1)
            for c in range(c0 + 1, c1)
        ]
        needed = sum(1 for r, c in interior if (r + c) % 2 == (r0 + c0 + 2) % 2)
        fill_color = next(
            (m for m, count in marker_counts.items() if count == needed),
            None,
        )
        if fill_color is not None:
            for r, c in interior:
                if (r + c) % 2 == (r0 + c0 + 2) % 2:
                    out[r][c] = fill_color

    return out
